const [filterStatus, setFilterStatus] = useState('all');
const [isAddOpen, setIsAddOpen] = useState(false);
const [isNotificationOpen, setIsNotificationOpen] = useState(false);

const filteredTasks = tasks.filter((task) => {
  const matchesSearch = task.name.toLowerCase().includes(searchTerm.toLowerCase());
  const matchesStatus = filterStatus === 'all' || task.status === filterStatus;
  return matchesSearch && matchesStatus;
});

const handleAdd = () => {
  setIsAddOpen(true);
};

const handleAddClose = () => {
  setIsAddOpen(false);
};

const handleSearchChange = (e) => {
  setSearchTerm(e.target.value);
};

const handleStatusFilter = (status) => {
  setFilterStatus(status);
};

const handleMarkComplete = (id) => {
  const updatedTasks = tasks.map((task) => {
    if (task.id === id) {
      return {
        ...task,
        status: 'completed',
        completedAt: new Date().toISOString()
      };
    }
    return task;
  });
  setTasks(updatedTasks);
  setIsNotificationOpen(true);
};

const handleToggleAdd = () => {
  setIsAddOpen(!isAddOpen);
};

const Notification = ({ type = 'success', title = 'Task Completed', message = 'Design comp review passed!' }) => {
  const [isDismissed, setIsDismissed] = useState(false);

  if (isDismissed) return null;

  return (
    <div className={`fixed top-6 right-6 z-50 flex w-full max-w-sm flex-col items-center space-y-3 rounded-2xl bg-white/5 p-6 backdrop-blur-xl border border-white/10 animate-in fade-in scale-95 transition-all duration-300 backdrop-blur-lg shadow-2xl ${type === 'success' ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-rose-500/10 border-rose-500/30'}`}>
      <div className="w-10 h-10 rounded-full p-2 flex-shrink-0 bg-gradient-to-br from-transparent via-slate-900 to-slate-950 border border-white/10">
        {type === 'success' ? <CheckCircle2 className="w-6 h-6 text-emerald-400" /> : <X className="w-6 h-6 text-rose-400" />}
      </div>
      <div>
        <h4 className="text-sm font-semibold text-slate-200">{title}</h4>
        <p className="text-xs text-slate-400">{message}</p>
      </div>
      <button className="absolute top-2 right-2 p-1.5 rounded-xl bg-white/5 hover:bg-white/10 text-slate-400 hover:text-slate-200" onClick={() => setIsDismissed(true)}>
        <X className="w-4 h-4" />
      </button>
    </div>
  );
};

